 for j,group:=range groups {core,edges:=group[0],0;var revenue int64;for _,i:=range group {edges+=len(adj[i]);revenue+=a.Revenue[i];if len(adj[i])>len(adj[core])||len(adj[i])==len(adj[core])&&a.MainSupport.count([]int{i})>a.MainSupport.count([]int{core}) {core=i}};lines=append(lines,fmt.Sprintf("GROUP %d items %d edges %d core %s revenue %s share %s members %s",j+1,len(group),edges/2,a.Names[core],money(revenue),percent(revenue,a.TotalRevenue),itemset(group,a.Names)))}
