 var lines []string;ranked:=append([]int(nil),a.ProductIDs...);sort.Slice(ranked,func(i,j int)bool{x,y:=ranked[i],ranked[j];if a.Revenue[x]!=a.Revenue[y] {return a.Revenue[x]>a.Revenue[y]};return x<y});categoryRevenue:=map[int]int64{};categoryUnits:=map[int]int64{};categoryItems:=map[int]int{}
